using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Collections.Generic;
class IconBuilder {
static GraphicsPath Round(float x,float y,float w,float h,float r){var p=new GraphicsPath();p.AddArc(x,y,r,r,180,90);p.AddArc(x+w-r,y,r,r,270,90);p.AddArc(x+w-r,y+h-r,r,r,0,90);p.AddArc(x,y+h-r,r,r,90,90);p.CloseFigure();return p;}
static void Main(){using(var b=new Bitmap(512,512)){using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.Transparent);using(var fill=new LinearGradientBrush(new Point(60,30),new Point(450,490),Color.FromArgb(147,124,217),Color.FromArgb(75,57,126))){fill.WrapMode=WrapMode.TileFlipXY;g.FillPath(fill,Round(18,18,476,476,110));}g.FillPath(new SolidBrush(Color.FromArgb(35,32,15,70)),Round(121,100,290,344,38));g.FillPath(Brushes.White,Round(108,82,284,344,38));using(var pen=new Pen(Color.FromArgb(230,224,244),9)){g.DrawLine(pen,153,346,287,346);g.DrawLine(pen,153,374,250,374);}using(var pen=new Pen(Color.FromArgb(105,81,162),15)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawBezier(pen,new Point(248,310),new Point(245,249),new Point(274,211),new Point(300,162));g.DrawBezier(pen,new Point(254,264),new Point(224,259),new Point(202,240),new Point(184,220));}var leaf=new GraphicsPath();leaf.AddBezier(267,218,266,165,302,135,340,137);leaf.AddBezier(340,137,338,188,309,221,267,218);g.FillPath(new SolidBrush(Color.FromArgb(110,167,139)),leaf);var small=new GraphicsPath();small.AddBezier(240,266,204,269,173,246,167,208);small.AddBezier(167,208,207,206,235,230,240,266);g.FillPath(new SolidBrush(Color.FromArgb(157,133,207)),small);}b.Save("assets/zhiji-icon.png",ImageFormat.Png);var sizes=new[]{16,24,32,48,64,128,256};var data=new List<byte[]>();foreach(int size in sizes){using(var resized=new Bitmap(size,size)){using(var g=Graphics.FromImage(resized)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(b,0,0,size,size);}using(var m=new MemoryStream()){resized.Save(m,ImageFormat.Png);data.Add(m.ToArray());}}}using(var w=new BinaryWriter(File.Create("assets/zhiji.ico"))){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)0);w.Write((byte)0);w.Write((ushort)1);w.Write((ushort)32);w.Write(data[i].Length);w.Write(offset);offset+=data[i].Length;}foreach(var item in data)w.Write(item);}}}
